package com.wellcheck.service;
import com.wellcheck.dto.ApiDtos.AerialRequest; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class AiGatewayService {
 private final RestClient client; private final JdbcTemplate jdbc; public AiGatewayService(@Value("${wellcheck.ai-url}") String url,JdbcTemplate j){client=RestClient.builder().baseUrl(url).build();jdbc=j;}
 public Map<?,?> analyse(Map<String,Object> request){try{return client.post().uri("/v1/report-analysis").contentType(MediaType.APPLICATION_JSON).body(request).retrieve().body(Map.class);}catch(Exception e){throw new IllegalArgumentException("AI service is unavailable; no analysis was fabricated");}}
 public Map<?,?> createMission(UUID requester,AerialRequest request){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO aerial_missions(id,name,status,requested_by) VALUES(?,?,'QUEUED',?)",id,request.name(),requester);try{var body=Map.of("mission_id",id.toString(),"footage_path",request.footagePath()==null?"":request.footagePath(),"telemetry",request.telemetry()==null?Map.of():request.telemetry());var response=client.post().uri("/v1/aerial/missions").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);jdbc.update("UPDATE aerial_missions SET status='PROCESSING',updated_at=now() WHERE id=?",id);return response;}catch(Exception e){jdbc.update("UPDATE aerial_missions SET status='FAILED',error_detail=?,updated_at=now() WHERE id=?","AI service unavailable",id);throw new IllegalArgumentException("Aerial processing service is unavailable; mission retained as failed");}}
 public List<Map<String,Object>> missions(){return jdbc.queryForList("SELECT id,name,status,error_detail AS \"errorDetail\",created_at AS \"createdAt\" FROM aerial_missions ORDER BY created_at DESC");}
}

